const activity = $("Etkinlik Sonucunu Normalize Et").first().json.result || {};
const lead     = $("Müşteri Adını Bul").first().json.result || {};
const yorumlar = $("Son Yorumu Çek").first().json.result || [];

const personeller = {
  "23180": "Abdullah Açıkgöz",
  "17984": "Ali Karaoğlu",
  "22186": "Ali Kemal Çınar",
  "26120": "Sefa Tuna Şencan",
  "26352": "Emre Caner",
  "1174": "Arda Kağan Ertaş",
  "116": "Merve Gelleci",
  "25258": "Murat Çakıroğlu",
  "5778": "Tuğba Kütük",
  "11690": "Zeliha Bilginsoy",
  "25314": "Hatice Aldemir",
  "25120": "Ozan Kabagöz",
  "27876": "Yiğitcan Dilek",
  "27878": "Aleyna Özdemir",
  "27446": "Beril Sarıyıldız",
  "27332": "Rüstem Sarıoğlan",
  "29484": "Enes Can Yıldırım",
  "22182": "Zarife Ayoğlu"
};


const userId = String(activity.RESPONSIBLE_ID || activity.AUTHOR_ID || "");
if (!personeller[userId]) return [];

const sorumluIsim = personeller[userId];
const musteriAdi = lead.TITLE || ((lead.NAME || '') + ' ' + (lead.LAST_NAME || '')).trim() || `Lead ID: ${activity.OWNER_ID || ''}`;

const provider = String(activity.PROVIDER_ID || '').toUpperCase();
const subject  = String(activity.SUBJECT || '');
const subjectU = subject.toUpperCase();
const desc     = String(activity.DESCRIPTION || '');
const descU    = desc.toUpperCase();

let tur = 'Diğer';
if (provider === 'CRM_TODO') tur = 'Evrensel Görev (Todo)';
else if (provider === 'CRM_EXTERNAL_CHANNEL') tur = 'Açık Hat / Canlı Destek';
else if (String(activity.TYPE_ID) === '1') tur = 'Toplantı / Yüz Yüze';
else if (String(activity.TYPE_ID) === '2') tur = 'Arama';
else if (String(activity.TYPE_ID) === '3') tur = 'Görev';
else if (String(activity.TYPE_ID) === '4') tur = 'E-Posta';

if (subjectU.includes('SMS') || provider.includes('SMS')) tur = 'SMS Gönderimi';
if (provider.includes('WHATSAPP') || subjectU.includes('WHATSAPP') || descU.includes('WHATSAPP')) tur = 'WhatsApp Mesajı';

const completed = String(activity.COMPLETED || '').toUpperCase() === 'Y';
const durum = completed ? 'Tamamlandı' : 'Bekliyor';

let deadlineRaw = String(activity.DEADLINE || '');
if (deadlineRaw.startsWith('9999')) deadlineRaw = '';
if (!deadlineRaw) deadlineRaw = String(activity.START_TIME || '');
if (deadlineRaw.startsWith('9999')) deadlineRaw = '';

const now = $now.setZone('Europe/Istanbul');
const today = now.startOf('day');
let deadlineDurum = 'Tarihsiz';
let deadlineFmt = 'Tarih Girilmemiş';

if (deadlineRaw) {
  deadlineFmt = deadlineRaw.substring(0,16).replace('T',' ');
  const d = DateTime.fromISO(deadlineRaw, { zone: 'Europe/Istanbul' });
  if (d.isValid) {
    const day = d.startOf('day');
    if (day < today) deadlineDurum = 'Geçmiş';
    else if (day.equals(today)) deadlineDurum = 'Bugün';
    else deadlineDurum = 'İleri Tarih';
  }
}

// Gün içi unutulan: son tarihi bugün ve saati GEÇMİŞ, hâlâ açık (saati gelmemiş olan unutulmuş sayılmaz).
const deadlineDt = deadlineRaw ? DateTime.fromISO(deadlineRaw, { zone: 'Europe/Istanbul' }) : null;
const gunIciUnutulan = (!completed && deadlineDurum === 'Bugün' && deadlineDt?.isValid && deadlineDt <= now) ? 1 : 0;

let sonYorum = '-';
if (Array.isArray(yorumlar) && yorumlar[0]?.COMMENT) {
  sonYorum = String(yorumlar[0].COMMENT).replace(/<[^>]*>?/gm,'').trim();
}
const yorumU = sonYorum.toUpperCase();
const isWA = tur === 'WhatsApp Mesajı' || descU.includes('WHATSAPP') || yorumU.includes('WHATSAPP') || yorumU.includes('WA MESSENGER') ? 1 : 0;
const isMail = tur === 'E-Posta' || descU.includes('E-POSTA') || yorumU.includes('E-POSTA') || yorumU.includes('MAIL') ? 1 : 0;

let tarih = now.toFormat('dd.MM.yyyy HH:mm');
const created = String(activity.CREATED || '');
if (created.length >= 16) {
  tarih = `${created.substring(8,10)}.${created.substring(5,7)}.${created.substring(0,4)} ${created.substring(11,16)}`;
}

return [{ json: {
  'Tarih': tarih,
  'Sorumlu Danışman': sorumluIsim,
  'Müşteri / Lead Adı': musteriAdi,
  'Etkinlik Türü': tur,
  'Etkinlik Konusu': subject || 'Konu Yok',
  'Planlanan Tarih': deadlineFmt,
  'Durum': durum,
  'Açıklama / Not': desc.replace(/<[^>]*>?/gm,'').split('**Transcript:**')[0].trim() || 'Detay yok',
  'Son Yorum': sonYorum,
  'WhatsApp_Mi': isWA,
  'EPosta_Mi': isMail,
  'Etkinlik_ID': String(activity.ID || ''),
  'Deadline Durumu': deadlineDurum,
  'Gün İçi Unutulan': gunIciUnutulan
}}];

const result = $json.result;
const activity = Array.isArray(result) ? result[0] : result;
if (!activity || !activity.ID) return [];

// Bu panel yalnızca Lead etkinliklerini raporlar.
if (String(activity.OWNER_TYPE_ID || '') !== '1') return [];

return [{ json: { result: activity } }];

// Bitrix giden webhook gövdesi form-urlencoded gelir. n8n sürümüne göre anahtarlar düz
// ("data[FIELDS][ID]") veya iç içe (data.FIELDS.ID) olabilir; ikisi de desteklenir.
const body = $json.body || {};
const at = (obj, key) => {
  if (obj && Object.prototype.hasOwnProperty.call(obj, key)) return obj[key];
  return key.replace(/\[/g, '.').replace(/\]/g, '').split('.').reduce((v, k) => v && typeof v === 'object' ? v[k] : undefined, obj);
};
const pick = (...keys) => {
  for (const key of keys) {
    const value = at(body, key);
    if (value !== undefined && value !== null && typeof value !== 'object' && String(value).trim() !== '') return value;
  }
  return '';
};

const event = String(pick('event', 'EVENT')).toUpperCase();
if (event === 'ONCRMACTIVITYDELETE') return [];

const rawDoc = pick('document_id[2]', 'DOCUMENT_ID[2]', 'documentId[2]');
const activityId = String(pick('data[FIELDS][ID]', 'DATA[FIELDS][ID]', 'FIELDS[ID]', 'ID', 'id', 'activity_id', 'ACTIVITY_ID')).trim();

let ownerType = '';
let ownerTypeId = '';
let ownerId = '';
const typeMap = { LEAD: 1, DEAL: 2, CONTACT: 3, COMPANY: 4 };
const reverseTypeMap = { '1': 'LEAD', '2': 'DEAL', '3': 'CONTACT', '4': 'COMPANY' };
const docMatch = String(rawDoc || '').match(/^(LEAD|DEAL|CONTACT|COMPANY)_(\d+)$/i);

if (docMatch) {
  ownerType = docMatch[1].toUpperCase();
  ownerTypeId = typeMap[ownerType];
  ownerId = docMatch[2];
} else {
  ownerTypeId = pick('data[FIELDS][OWNER_TYPE_ID]', 'DATA[FIELDS][OWNER_TYPE_ID]', 'FIELDS[OWNER_TYPE_ID]', 'OWNER_TYPE_ID', 'ownerTypeId');
  ownerId = pick('data[FIELDS][OWNER_ID]', 'DATA[FIELDS][OWNER_ID]', 'FIELDS[OWNER_ID]', 'OWNER_ID', 'ownerId');
  ownerType = reverseTypeMap[String(ownerTypeId)] || '';
}

if (!/^\d+$/.test(activityId) && (!ownerTypeId || !ownerId)) return [];

return [{
  json: {
    event: event || 'ROBOT',
    activityId: /^\d+$/.test(activityId) ? activityId : '',
    ownerType,
    ownerTypeId: ownerTypeId ? Number(ownerTypeId) : '',
    ownerId: ownerId ? String(ownerId) : '',
    rawDocumentId: rawDoc || ''
  }
}];

// XRE Gün Sonu Etkinlik / Tamamlama / Arama Raporu (v3)
// Kaynaklar (hepsi bu Code düğümünden önce, sırayla ve "Execute Once" ile çalışır):
//   Bitrix Rapor - Kullanıcılar                 user.get (ACTIVE)            -> ID → isim
//   Bitrix Rapor - Bugün Oluşturulan Etkinlikler crm.activity.list CREATED bugün
//   Bitrix Rapor - Bugün Güncellenen Etkinlikler crm.activity.list LAST_UPDATED bugün
//   Bitrix Rapor - Bugün Vadesi Olan Todo'lar    CRM_TODO, DEADLINE bugün (açık+kapalı)
//   Bitrix Rapor - Geciken Açık Todo'lar         CRM_TODO, COMPLETED=N, DEADLINE < bugün
//   Bitrix Rapor - Bugün Gelen Leadler           crm.lead.list DATE_CREATE bugün
//   Bitrix Rapor - Bugünkü Çağrılar              voximplant.statistic.get bugün
//   Etkinlik Günlüğünü Oku                       webhook kolunun yazdığı durum geçmişi
//
// "Tamamlandı'ya basma" sayısı Bitrix listesinden okunamaz (Bitrix tamamlama zamanı ve
// tamamlayanı tutmaz). Bu yüzden webhook kolu her etkinlik sürümünü "Etkinlik Günlüğü"
// sekmesine yazar; burada Bekliyor → Tamamlandı geçişleri sayılır. Günlük boşsa
// yaklaşık değer (bugün güncellenmiş ve şu an tamamlanmış) kullanılır ve raporda belirtilir.

const ZONE = 'Europe/Istanbul';
const KONUSMA_ESIK = 20;
const CEVAPSIZ_KOD = new Set(['603', '603-S', '486', '480', '487', '408', '304']); // sn; bu süre ve üzeri başarılı arama "geçerli görüşme"
const CRM_HOST = 'https://xre.bitrix24.com.tr';
const WEBHOOK = CRM_HOST + '/rest/1/<BITRIX_WEBHOOK_TOKEN>/';

// Rapor kapsamındaki personel. Listede olup hiç kaydı olmayanlar da 0 ile gösterilir.
const PERSONELLER = {
  '23180': { isim: 'Abdullah Açıkgöz', birim: 'Arsa' },
  '17984': { isim: 'Ali Karaoğlu', birim: 'Proje Satış' },
  '22186': { isim: 'Ali Kemal Çınar', birim: 'Proje Satış' },
  '26120': { isim: 'Sefa Tuna Şencan', birim: 'Proje Satış' },
  '26352': { isim: 'Emre Caner', birim: 'Proje Satış' },
  '1174': { isim: 'Arda Kağan Ertaş', birim: 'Proje Satış' },
  '116': { isim: 'Merve Gelleci', birim: 'Proje Satış' },
  '25258': { isim: 'Murat Çakıroğlu', birim: 'Proje Satış' },
  '5778': { isim: 'Tuğba Kütük', birim: 'Proje Satış' },
  '11690': { isim: 'Zeliha Bilginsoy', birim: 'Proje Satış' },
  '25314': { isim: 'Hatice Aldemir', birim: 'Barter' },
  '25120': { isim: 'Ozan Kabagöz', birim: 'Barter', gorev: 'Avukat' },
  '27876': { isim: 'Yiğitcan Dilek', birim: 'Barter' },
  '27878': { isim: 'Aleyna Özdemir', birim: 'Barter' },
  '27446': { isim: 'Beril Sarıyıldız', birim: 'Partners' },
  '27332': { isim: 'Rüstem Sarıoğlan', birim: 'Franchise' },
  '29484': { isim: 'Enes Can Yıldırım', birim: 'Auto' },
  '22182': { isim: 'Zarife Ayoğlu', birim: 'Recruiting' }
};

const simdi = $now.setZone(ZONE);
const bugun = simdi.startOf('day');
const yarin = bugun.plus({ days: 1 });
const todayStr = simdi.toFormat('dd.MM.yyyy');
const saatStr = simdi.toFormat('HH:mm');

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[c]));
}
function hms(seconds) {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  return [Math.floor(s / 3600), Math.floor((s % 3600) / 60), s % 60].map(x => String(x).padStart(2, '0')).join(':');
}
function uidOf(v) {
  const m = /^(?:user_)?([1-9]\d*)(?:\.0+)?$/i.exec(String(v ?? '').trim());
  return m ? m[1] : '';
}
function dt(v) {
  const s = String(v ?? '').trim();
  if (!s || s.startsWith('0000') || s.startsWith('9999')) return null;
  let d = DateTime.fromISO(s, { zone: ZONE });
  if (!d.isValid) {
    for (const f of ['dd.MM.yyyy HH:mm:ss', 'dd.MM.yyyy HH:mm', 'yyyy-MM-dd HH:mm:ss']) {
      d = DateTime.fromFormat(s, f, { zone: ZONE });
      if (d.isValid) break;
    }
  }
  return d.isValid ? d.setZone(ZONE) : null;
}

const hatalar = [];
function safeAll(nodeName) {
  try { return $(nodeName).all().map(i => i?.json || {}); }
  catch (e) { hatalar.push(nodeName + ': düğüm çalışmadı (' + e.message + ')'); return []; }
}
function bitrixRows(nodeName) {
  const rows = [];
  for (const page of safeAll(nodeName)) {
    const r = page?.body && typeof page.body === 'object' ? page.body : page;
    if (r?.error) { hatalar.push(nodeName + ': ' + (r.error_description || r.error)); continue; }
    const res = r?.result;
    if (Array.isArray(res)) rows.push(...res);
    else if (Array.isArray(res?.items)) rows.push(...res.items);
    else if (Array.isArray(res?.activities)) rows.push(...res.activities);
  }
  // Sayfa kaymasında aynı kayıt iki kez gelebilir.
  const seen = new Set();
  return rows.filter(r => {
    const k = String(r?.ID ?? r?.CALL_ID ?? '');
    if (!k) return true;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

// ---------- Kaynaklar ----------
const kullanicilar = bitrixRows('Bitrix Rapor - Kullanıcılar');
const olusturulan = bitrixRows('Bitrix Rapor - Bugün Oluşturulan Etkinlikler');
const guncellenen = bitrixRows('Bitrix Rapor - Bugün Güncellenen Etkinlikler');
const vadesiBugun = bitrixRows("Bitrix Rapor - Bugün Vadesi Olan Todo'lar");
const gecikenAcik = bitrixRows("Bitrix Rapor - Geciken Açık Todo'lar");
const yeniLeadler = bitrixRows('Bitrix Rapor - Bugün Gelen Leadler');
const cagrilar = bitrixRows('Bitrix Rapor - Bugünkü Çağrılar');
const gunluk = safeAll('Etkinlik Günlüğünü Oku').filter(r => r && r['Etkinlik_ID']);

const isimler = {};
for (const u of kullanicilar) {
  const id = uidOf(u.ID);
  const ad = [u.NAME, u.LAST_NAME].map(x => String(x || '').trim()).filter(Boolean).join(' ');
  if (id && ad) isimler[id] = ad;
}
for (const [id, p] of Object.entries(PERSONELLER)) isimler[id] = p.isim;
const isim = uid => isimler[uid] || ('Kullanıcı #' + uid);

// ---------- Kişi istatistikleri ----------
const stats = new Map();
function S(uid) {
  if (!stats.has(uid)) {
    stats.set(uid, {
      todoOlusturulan: 0,   // bugün oluşturulan ve sorumlusu kendisi olan Todo
      vadesiBugun: 0,       // son tarihi bugün olan Todo (açık+kapalı)
      vadesiBugunTamam: 0,  // bunların tamamlanmış olanı
      tamamlamaBasma: 0,    // bugün "Tamamlandı"ya basma adedi (basan kişi = EDITOR)
      tekilTamamlanan: new Set(),
      zamanindaTamam: 0,    // son tarihten önce/aynı anda tamamlanan
      gecTamam: 0,          // son tarihi geçtikten sonra tamamlanan
      yenidenAcma: 0,       // tamamlandı → bekliyor geri alma
      aramasizTamam: new Set(), // lead'i bugün hiç aranmadan tamamlanan Todo
      gunIciUnutulan: 0,    // son tarihi bugün, saati geçmiş, hâlâ açık
      bugunKalanAcik: 0,    // son tarihi bugün, saati henüz gelmemiş, açık
      oncekiGeciken: 0,     // son tarihi bugünden önce, hâlâ açık
      aradiTamamlamadi: new Set(), // bugün aradığı lead'de vadesi gelmiş açık Todo kaldı
      aramaDenemesi: 0, aramaBasarili: 0, cevapsiz: 0, digerSonuc: 0, gelen: 0,
      gecerliArama: 0, gecerliSure: 0, gecerliNumara: new Set(),
      yeniLead: new Set(), arananYeniLead: new Set()
    });
  }
  return stats.get(uid);
}
for (const uid of Object.keys(PERSONELLER)) S(uid);

const isLead = a => String(a?.OWNER_TYPE_ID ?? '') === '1';
const isTodo = a => String(a?.PROVIDER_ID || '').toUpperCase() === 'CRM_TODO';
const isDone = a => String(a?.COMPLETED || '').toUpperCase() === 'Y';

// Aynı etkinlik birden fazla listede gelir; en güncel kopya (LAST_UPDATED en büyük) tutulur.
const aktivite = new Map();
for (const a of [...olusturulan, ...vadesiBugun, ...gecikenAcik, ...guncellenen]) {
  const id = String(a?.ID || '');
  if (!id || !isLead(a)) continue;
  const prev = aktivite.get(id);
  const t = dt(a.LAST_UPDATED)?.toMillis() ?? 0;
  if (!prev || t >= (dt(prev.LAST_UPDATED)?.toMillis() ?? 0)) aktivite.set(id, a);
}
const olusturulanId = new Set(olusturulan.map(a => String(a.ID)));

// ---------- Aramalar ----------
const leadAranan = new Map(); // uid -> Set(leadId) bugün aradığı lead'ler
const leadHerhangiArama = new Set(); // bugün kim olursa olsun aranan lead'ler
// Bitrix aramaların çoğunu lead'e değil bağlı kişiye (CONTACT) yazar; bu yüzden aranan numara ve kişi de tutulur.
// Anahtarlar: 'L:<leadId>', 'K:<contactId>', 'T:<son 10 hane>' -> o anahtara yapılan en son aramanın zamanı (ms).
const telNorm = v => { const d = String(v ?? '').replace(/\D/g, ''); return d.length >= 10 ? d.slice(-10) : ''; };
// Personelin kendi hat numaraları: bu numaralara/bu numaralardan yapılan aramalar müşteri araması sayılmaz
// (bazı lead kartlarına personel numarası yazılmış; o lead'ler yanlışlıkla "arandı" görünmesin).
const PERSONEL_TEL = new Set(['5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX','5XXXXXXXXX']);
const gidenZaman = new Map(); // uid -> Map(anahtar -> ms)  yalnızca GİDEN aramalar
const herhangiZaman = new Map(); // anahtar -> ms  herkesin tüm aramaları
const zamanYaz = (map, key, ms) => { if (!(map.get(key) >= ms)) map.set(key, ms); };
const cagriSayisi = cagrilar.length;
for (const c of cagrilar) {
  const uid = uidOf(c.PORTAL_USER_ID);
  if (!uid) continue;
  const s = S(uid);
  const code = String(c.CALL_FAILED_CODE || '').trim();
  const sure = parseInt(c.CALL_DURATION, 10) || 0;
  const tip = String(c.CALL_TYPE || '');
  const giden = tip === '1' || tip === '4';
  if (giden) {
    s.aramaDenemesi++;
    if (code === '200') s.aramaBasarili++;
    // Cevapsız: karşı taraf açmadı/reddetti/meşgul (603, 603-S, 486, 480, 487, 408, 304).
    // Diğer kodlar (503 hat hatası, 500 yapılandırma, 403 izin yok, 404 geçersiz no ...) teknik/engelli sayılır.
    else if (CEVAPSIZ_KOD.has(code)) s.cevapsiz++;
    else s.digerSonuc++;
  } else if (tip === '2' || tip === '3') s.gelen++;
  if (code === '200' && sure >= KONUSMA_ESIK) {
    s.gecerliArama++;
    s.gecerliSure += sure;
    const tel = String(c.PHONE_NUMBER || '').replace(/\D/g, '').slice(-10);
    if (tel) s.gecerliNumara.add(tel);
  }
  if (String(c.CRM_ENTITY_TYPE || '').toUpperCase() === 'LEAD' && c.CRM_ENTITY_ID) {
    const lid = String(c.CRM_ENTITY_ID);
    leadHerhangiArama.add(lid);
    if (!leadAranan.has(uid)) leadAranan.set(uid, new Set());
    leadAranan.get(uid).add(lid);
  }
  {
    const ms = dt(c.CALL_START_DATE)?.toMillis() ?? 0;
    const tel10 = telNorm(c.PHONE_NUMBER);
    const personelNo = tel10 && PERSONEL_TEL.has(tel10);
    const tipU = String(c.CRM_ENTITY_TYPE || '').toUpperCase();
    const anahtarlar = [];
    if (tipU === 'LEAD' && c.CRM_ENTITY_ID) anahtarlar.push('L:' + c.CRM_ENTITY_ID);
    if (!personelNo) {
      if (tel10) anahtarlar.push('T:' + tel10);
      if (tipU === 'CONTACT' && c.CRM_ENTITY_ID) anahtarlar.push('K:' + c.CRM_ENTITY_ID);
    }
    for (const k of anahtarlar) {
      zamanYaz(herhangiZaman, k, ms);
      if (giden) { if (!gidenZaman.has(uid)) gidenZaman.set(uid, new Map()); zamanYaz(gidenZaman.get(uid), k, ms); }
    }
  }
}

// ---------- Lead telefon / bağlı kişi bilgisi ----------
// Yeni lead'lerde sorgudan gelir; görevlerin lead'leri için Bitrix'ten 50'şerli batch ile okunur.
const leadBilgi = new Map(); // leadId -> { tel: Set(10 hane), kisi: contactId }
const leadBilgiEkle = l => {
  const id = String(l?.ID || '');
  if (!id) return;
  const tel = new Set((Array.isArray(l.PHONE) ? l.PHONE : []).map(p => telNorm(p?.VALUE)).filter(t => t && !PERSONEL_TEL.has(t)));
  const kisi = l.CONTACT_ID && String(l.CONTACT_ID) !== '0' ? String(l.CONTACT_ID) : '';
  leadBilgi.set(id, { tel, kisi });
};
yeniLeadler.forEach(leadBilgiEkle);
{
  const gerekli = new Set();
  for (const a of aktivite.values()) if (isTodo(a) && a.OWNER_ID) gerekli.add(String(a.OWNER_ID));
  for (const r of gunluk) if (r['Lead ID']) gerekli.add(String(r['Lead ID']));
  const idler = [...gerekli].filter(id => /^\d+$/.test(id) && !leadBilgi.has(id));
  const parcalar = [];
  for (let i = 0; i < idler.length; i += 50) parcalar.push(idler.slice(i, i + 50));
  try {
    for (let i = 0; i < parcalar.length; i += 50) {
      const cmd = {};
      parcalar.slice(i, i + 50).forEach((p, j) => {
        cmd['l' + (i + j)] = 'crm.lead.list?' + p.map(id => 'filter%5B%40ID%5D%5B%5D=' + id).join('&') + '&select%5B%5D=ID&select%5B%5D=PHONE&select%5B%5D=CONTACT_ID';
      });
      const b = await this.helpers.httpRequest({ method: 'POST', url: WEBHOOK + 'batch.json', body: { halt: 0, cmd }, json: true, timeout: 60000 });
      if (b?.error) throw new Error(b.error_description || b.error);
      const sonuc = b?.result?.result || {};
      const hata = b?.result?.result_error || {};
      for (const k of Object.keys(cmd)) {
        if (hata[k]) throw new Error(k + ': ' + JSON.stringify(hata[k]).slice(0, 150));
        (Array.isArray(sonuc[k]) ? sonuc[k] : []).forEach(leadBilgiEkle);
      }
    }
  } catch (e) {
    hatalar.push('Lead telefonları okunamadı; arama eşleşmesi yalnızca lead ID ile yapıldı (' + String(e.message || e).slice(0, 150) + ')');
  }
}

// Lead, verilen andan (sonrasi, ms) sonra arandı mı?
// uid verilirse yalnızca o kişinin GİDEN aramaları; verilmezse herkesin tüm aramaları.
function leadArandi(leadId, uid, sonrasi = 0) {
  const id = String(leadId || '');
  if (!id) return false;
  const map = uid ? gidenZaman.get(uid) : herhangiZaman;
  if (!map) return false;
  const b = leadBilgi.get(id);
  const anahtarlar = ['L:' + id];
  if (b?.kisi) anahtarlar.push('K:' + b.kisi);
  if (b) for (const t of b.tel) anahtarlar.push('T:' + t);
  return anahtarlar.some(k => map.has(k) && map.get(k) >= sonrasi);
}

// ---------- Yeni lead'ler ----------
for (const l of yeniLeadler) {
  const uid = uidOf(l.ASSIGNED_BY_ID);
  const id = String(l.ID || '');
  if (!uid || !id) continue;
  const s = S(uid);
  s.yeniLead.add(id);
  // Yeni lead: sorumlusu, lead oluştuktan SONRA aramış mı?
  if (leadArandi(id, uid, dt(l.DATE_CREATE)?.toMillis() ?? 0)) s.arananYeniLead.add(id);
}

// ---------- Todo durumları (anlık) ----------
for (const a of aktivite.values()) {
  if (!isTodo(a)) continue;
  const uid = uidOf(a.RESPONSIBLE_ID);
  if (!uid) continue;
  const s = S(uid);
  const id = String(a.ID);
  const deadline = dt(a.DEADLINE);
  const done = isDone(a);
  if (olusturulanId.has(id)) s.todoOlusturulan++;
  if (deadline && deadline >= bugun && deadline < yarin) {
    s.vadesiBugun++;
    if (done) s.vadesiBugunTamam++;
    else if (deadline <= simdi) s.gunIciUnutulan++;
    else s.bugunKalanAcik++;
  }
  if (!done && deadline && deadline < bugun) s.oncekiGeciken++;
  // Aradı ama tamamlamadı: bugün bu lead'i aramış, vadesi gelmiş Todo hâlâ açık.
  // Görev oluşturulduktan SONRA aranmış ama görev hâlâ açık (öncesindeki arama yeni takip görevini doğurur, sayılmaz)
  if (!done && deadline && deadline <= simdi && leadArandi(a.OWNER_ID, uid, dt(a.CREATED)?.toMillis() ?? 0)) {
    s.aradiTamamlamadi.add(String(a.OWNER_ID));
  }
}

// ---------- Tamamlama geçişleri (Etkinlik Günlüğü) ----------
// Günlük satırı: Etkinlik_ID, Durum (Tamamlandı/Bekliyor), Son Güncelleme (Bitrix LAST_UPDATED),
// Değiştiren ID (EDITOR_ID = butona basan), Sorumlu ID, Lead ID, Son Tarih, Tür, Kayıt Zamanı.
const gunlukTodo = gunluk.filter(r => String(r['Tür'] || '').toUpperCase() === 'CRM_TODO');
let gunlukKullanildi = false;
const byId = new Map();
for (const r of gunlukTodo) {
  const id = String(r['Etkinlik_ID']);
  if (!byId.has(id)) byId.set(id, []);
  byId.get(id).push(r);
}
for (const [id, list] of byId) {
  list.sort((a, b) => ((dt(a['Son Güncelleme']) || dt(a['Kayıt Zamanı']))?.toMillis() ?? 0) - ((dt(b['Son Güncelleme']) || dt(b['Kayıt Zamanı']))?.toMillis() ?? 0));
  let onceki = null;
  for (const r of list) {
    const durum = String(r['Durum'] || '');
    const t = dt(r['Son Güncelleme']) || dt(r['Kayıt Zamanı']);
    const bugunMu = t && t >= bugun && t < yarin;
    const basan = uidOf(r['Değiştiren ID']) || uidOf(r['Sorumlu ID']);
    if (durum === 'Tamamlandı' && onceki !== 'Tamamlandı' && bugunMu && basan) {
      gunlukKullanildi = true;
      const s = S(basan);
      s.tamamlamaBasma++;
      s.tekilTamamlanan.add(id);
      const deadline = dt(r['Son Tarih']);
      if (deadline && t > deadline) s.gecTamam++; else s.zamanindaTamam++;
      const lid = String(r['Lead ID'] || '');
      if (lid && !leadArandi(lid, null)) s.aramasizTamam.add(id);
    }
    if (durum === 'Bekliyor' && onceki === 'Tamamlandı' && bugunMu && basan) S(basan).yenidenAcma++;
    onceki = durum;
  }
}
// Günlük boşsa yaklaşık değer: bugün güncellenmiş ve şu an tamamlanmış Todo (sorumlusuna yazılır).
if (!gunlukKullanildi) {
  for (const a of aktivite.values()) {
    if (!isTodo(a) || !isDone(a)) continue;
    const t = dt(a.LAST_UPDATED);
    if (!t || t < bugun || t >= yarin) continue;
    const uid = uidOf(a.EDITOR_ID) || uidOf(a.RESPONSIBLE_ID);
    if (!uid) continue;
    const s = S(uid);
    s.tamamlamaBasma++;
    s.tekilTamamlanan.add(String(a.ID));
    const deadline = dt(a.DEADLINE);
    if (deadline && t > deadline) s.gecTamam++; else s.zamanindaTamam++;
    if (!leadArandi(a.OWNER_ID, null)) s.aramasizTamam.add(String(a.ID));
  }
}

// ---------- Satırlar ----------
const satirlar = [...stats.entries()].map(([uid, s]) => ({
