  listed: Boolean(PERSONELLER[uid]),
  todoOlusturulan: s.todoOlusturulan,
  vadesiBugun: s.vadesiBugun,
  vadesiBugunTamam: s.vadesiBugunTamam,
  tamamlamaBasma: s.tamamlamaBasma,
  tekilTamamlanan: s.tekilTamamlanan.size,
  zamanindaTamam: s.zamanindaTamam,
  gecTamam: s.gecTamam,
  yenidenAcma: s.yenidenAcma,
  aramasizTamam: s.aramasizTamam.size,
  gunIciUnutulan: s.gunIciUnutulan,
  bugunKalanAcik: s.bugunKalanAcik,
  oncekiGeciken: s.oncekiGeciken,
  unutulanToplam: s.gunIciUnutulan + s.oncekiGeciken,
  aradiTamamlamadi: s.aradiTamamlamadi.size,
  aramaDenemesi: s.aramaDenemesi, aramaBasarili: s.aramaBasarili, cevapsiz: s.cevapsiz, digerSonuc: s.digerSonuc, gelen: s.gelen,
  gecerliArama: s.gecerliArama, gecerliSure: s.gecerliSure, gecerliKisi: s.gecerliNumara.size,
  yeniLead: s.yeniLead.size, arananYeniLead: s.arananYeniLead.size,
  aranmayanYeniLead: Math.max(0, s.yeniLead.size - s.arananYeniLead.size)
}))
  .filter(r => r.listed)
  .sort((a, b) => Number(b.listed) - Number(a.listed) || (b.tamamlamaBasma + b.aramaDenemesi) - (a.tamamlamaBasma + a.aramaDenemesi) || a.isim.localeCompare(b.isim, 'tr'));

const SAYISAL = ['todoOlusturulan', 'vadesiBugun', 'vadesiBugunTamam', 'tamamlamaBasma', 'tekilTamamlanan', 'zamanindaTamam', 'gecTamam', 'yenidenAcma', 'aramasizTamam', 'gunIciUnutulan', 'bugunKalanAcik', 'oncekiGeciken', 'unutulanToplam', 'aradiTamamlamadi', 'aramaDenemesi', 'aramaBasarili', 'cevapsiz', 'digerSonuc', 'gelen', 'gecerliArama', 'gecerliSure', 'gecerliKisi', 'yeniLead', 'arananYeniLead', 'aranmayanYeniLead'];
const toplam = Object.fromEntries(SAYISAL.map(k => [k, satirlar.reduce((t, r) => t + (r[k] || 0), 0)]));
const oran = (a, b) => b ? Math.round((a / b) * 100) + '%' : '-';

const kaynakNotu = gunlukKullanildi
