}
const sifirlar = satirlar.filter(r => r.listed && !(r.todoOlusturulan || r.vadesiBugun || r.tamamlamaBasma || r.unutulanToplam || r.aramaDenemesi || r.gelen || r.yeniLead)).map(r => r.isim);
tg += '\n━━━━━━━━━━━━━━━━━━━━\n';
