tg += `Unutulan açık etkinlik ${toplam.unutulanToplam} (bugün ${toplam.gunIciUnutulan} + önceki ${toplam.oncekiGeciken}) · aradı/kapatmadı ${toplam.aradiTamamlamadi} · aranmadan tamamlanan ${toplam.aramasizTamam}\n`;
tg += `Giden arama ${toplam.aramaDenemesi} · başarılı ${toplam.aramaBasarili} · ${KONUSMA_ESIK} sn+ ${toplam.gecerliArama} · ${hms(toplam.gecerliSure)}\n`;
if (sifirlar.length) tg += `\nKaydı görünmeyen: ${sifirlar.join(', ')}\n`;
tg += `\nℹ️ ${kaynakNotu}\nKaynak: ${aktivite.size} lead etkinliği · ${gecikenAcik.length} geciken açık Todo · ${cagriSayisi} çağrı · ${yeniLeadler.length} yeni lead · ${gunlukTodo.length} günlük satırı`;
if (hatalar.length) tg += `\n❗ Veri hatası: ${hatalar.join(' | ')}`;

// ---------- E-posta ----------
const th = (t, al = 'center') => `<th style="padding:8px;text-align:${al};border:1px solid #cfd8e3;">${esc(t)}</th>`;
