html += '<div style="padding:16px;overflow-x:auto;">';
if (!gunlukKullanildi) html += `<p style="background:#fff4ce;border:1px solid #e0c060;padding:10px;border-radius:6px;font-size:13px;">${esc(kaynakNotu)}</p>`;
