  html += KOLON.map(k => td(r[k[1]], r[k[1]] ? k[2] : 'color:#999;')).join('') + td(hms(r.gecerliSure)) + '</tr>';
});
html += '<tr style="background:#FFC000;font-weight:bold;"><td style="padding:8px;border:1px solid #dde4ec;">TOPLAM</td><td style="border:1px solid #dde4ec;"></td>' + KOLON.map(k => td(toplam[k[1]])).join('') + td(hms(toplam.gecerliSure)) + '</tr></tbody></table>';
