html += `<p>Kaynak: ${aktivite.size} lead etkinliği · ${gecikenAcik.length} geciken açık Todo · ${cagriSayisi} çağrı · ${yeniLeadler.length} yeni lead · ${gunlukTodo.length} günlük satırı.</p>`;
html += '</div></div></div>';

return [{
  json: {
    telegram_mesaj: tg,
    email_mesaj: html,
    gunluk_kullanildi: gunlukKullanildi,
    hatalar,
    toplam,
    satirlar,
    rapor_saati: simdi.toISO()
  }
}];

const report = $input.first()?.json || {};
let remaining = String(report.telegram_mesaj || '');
const maxLength = 3500;
const chunks = [];
while (remaining.length > maxLength) {
  let cut = remaining.lastIndexOf('\n', maxLength);
  if (cut < 1000) cut = maxLength;
  chunks.push(remaining.slice(0, cut));
  remaining = remaining.slice(cut).replace(/^\n+/, '');
}
if (remaining) chunks.push(remaining);
return chunks.map((chunk, index) => ({ json: { telegram_mesaj_parcasi: chunk, parca: index + 1, toplam_parca: chunks.length } }));

const responses = $input.all().map(item => item.json || {});
const failed = responses.find(response => response.ok !== true);
if (failed) {
  const body = failed.body && typeof failed.body === 'object' ? failed.body : failed;
  const yeniId = body.parameters?.migrate_to_chat_id;
  let mesaj = 'Telegram API mesajı reddetti: ' + String(body.description || failed.message || 'ok=true yanıtı alınmadı');
  if (yeniId) mesaj += ` — Grup süper gruba dönüştürülmüş; "Telegram Grubuna Gönder" düğümündeki chat_id değerini ${yeniId} yapın.`;
  throw new Error(mesaj);
}
return responses.map(json => ({ json }));

// Her etkinlik sürümünü (aynı sürüm önceki düğümde tekilleştirildi) "Etkinlik Günlüğü" sekmesine
